import React, { useState, useEffect } from 'react';
import { C, slides } from '../data';

export default function Hero() {
  const [current, setCurrent] = useState(0);

  useEffect(() => {
    const t = setInterval(() => setCurrent((c) => (c + 1) % slides.length), 5000);
    return () => clearInterval(t);
  }, []);

  const prev = () => setCurrent((c) => (c - 1 + slides.length) % slides.length);
  const next = () => setCurrent((c) => (c + 1) % slides.length);
  const slide = slides[current];

  return (
    <section id="hero" style={{ 
      position: 'relative', 
      minHeight: '100vh', 
      display: 'flex', 
      alignItems: 'center', 
      overflow: 'hidden',
      backgroundColor: '#000712' // Deep Blue base
    }}>

      {/* --- Full Background Image (HD Slide) --- */}
      <div style={{
        position: 'absolute',
        inset: 0,
        backgroundImage: `url(${slide.imageUrl})`,
        backgroundSize: 'cover',
        backgroundPosition: 'center',
        transition: 'background-image 1.2s cubic-bezier(0.4, 0, 0.2, 1)',
        zIndex: 1
      }} />

      {/* --- Professional Blue-Tint Overlay (Mirroring Image Style) --- */}
      <div style={{
        position: 'absolute',
        inset: 0,
        background: 'linear-gradient(105deg, rgba(10,25,47,0.95) 0%, rgba(10,25,47,0.4) 60%, rgba(0,0,0,0.8) 100%)',
        zIndex: 2
      }} />

      {/* --- Main Content Area --- */}
      <div style={{ 
        maxWidth: 1280, 
        margin: '0 auto', 
        padding: '0 24px', 
        width: '100%', 
        position: 'relative', 
        zIndex: 3,
        display: 'flex',
        alignItems: 'center',
        justifyContent: 'space-between',
        flexWrap: 'wrap',
        gap: '40px'
      }}>

        {/* --- Left: Text Content --- */}
        <div style={{ flex: '1 1 500px' }}>
          <div style={{ 
            display: 'inline-block', 
            padding: '8px 16px', 
            borderRadius: '4px', 
            fontSize: '12px', 
            fontWeight: 700, 
            textTransform: 'uppercase', 
            letterSpacing: '0.2em', 
            marginBottom: 24, 
            background: 'rgba(255,255,255,0.05)',
            borderLeft: `3px solid ${C.gold}`,
            color: C.goldLight,
            backdropFilter: 'blur(5px)'
          }}>
            {slide.tag}
          </div>

          <h1 style={{ 
            fontSize: 'clamp(2.5rem, 7vw, 4.2rem)', 
            fontWeight: 800, 
            color: '#fff', 
            fontFamily: "'Playfair Display', serif", 
            lineHeight: 1.1, 
            marginBottom: 24,
            textTransform: 'uppercase',
            letterSpacing: '-0.02em'
          }}>
            {slide.title}
          </h1>

          <p style={{ 
            fontSize: '1.15rem', 
            color: 'rgba(255,255,255,0.8)', 
            marginBottom: 40, 
            lineHeight: 1.6, 
            maxWidth: 550 
          }}>
            {slide.subtitle}
          </p>

          <div style={{ display: 'flex', flexWrap: 'wrap', gap: 16 }}>
            <button
              onClick={() => document.getElementById('contact')?.scrollIntoView({ behavior: 'smooth' })}
              style={{ 
                padding: '16px 40px', 
                borderRadius: '8px', 
                fontWeight: 700, 
                fontSize: '15px', 
                background: C.gold, 
                color: '#001a33', 
                border: 'none', 
                cursor: 'pointer', 
                boxShadow: `0 10px 25px ${C.gold}44`,
                transition: '0.3s' 
              }}
            >
              Join as Tutor
            </button>
            <button
              style={{ 
                padding: '16px 40px', 
                borderRadius: '8px', 
                fontWeight: 700, 
                fontSize: '15px', 
                background: 'transparent', 
                color: '#fff', 
                border: '2px solid rgba(255,255,255,0.4)', 
                cursor: 'pointer', 
                backdropFilter: 'blur(10px)',
                transition: '0.3s' 
              }}
            >
              Find a Tutor →
            </button>
          </div>
        </div>

        {/* --- Right: Floating Glass Card (From Image) --- */}
        <div style={{ flex: '1 1 320px', display: 'flex', justifyContent: 'center' }}>
          <div style={{
            width: '320px',
            background: 'rgba(255, 255, 255, 0.03)',
            backdropFilter: 'blur(15px)',
            border: '1px solid rgba(255, 255, 255, 0.1)',
            borderRadius: '24px',
            padding: '30px',
            textAlign: 'center',
            boxShadow: '0 25px 50px rgba(0,0,0,0.3)',
            animation: 'float 6s ease-in-out infinite'
          }}>
            {/* Badge Row */}
            <div style={{ display: 'flex', gap: '10px', justifyContent: 'center', marginBottom: '30px' }}>
              <div style={badgeStyle}>✔️ Verified</div>
              <div style={{...badgeStyle, background: 'rgba(245,166,35,0.15)', color: C.goldLight}}>👥 500+ Tutors</div>
            </div>

            {/* Icon Box */}
            <div style={{
              width: '180px',
              height: '180px',
              margin: '0 auto 20px',
              background: 'rgba(255,255,255,0.95)',
              borderRadius: '16px',
              display: 'flex',
              alignItems: 'center',
              justifyContent: 'center',
              boxShadow: '0 10px 30px rgba(0,0,0,0.1)'
            }}>
              <span style={{ fontSize: '100px', color: '#003366' }}>🎓</span>
            </div>

            <p style={{ color: '#fff', fontSize: '14px', fontWeight: 500, opacity: 0.9 }}>
              Quality Academic Support
            </p>
          </div>
        </div>
      </div>

      {/* --- Slider Controls (Bottom Right) --- */}
      <div style={{ 
        position: 'absolute', 
        bottom: 50, 
        right: 60, 
        zIndex: 10, 
        display: 'flex', 
        alignItems: 'center', 
        gap: 20 
      }}>
        <div style={{ display: 'flex', gap: 10 }}>
          {slides.map((_, i) => (
            <div 
              key={i} 
              onClick={() => setCurrent(i)}
              style={{ 
                width: i === current ? 40 : 10, 
                height: 5, 
                borderRadius: 99, 
                background: i === current ? C.gold : 'rgba(255,255,255,0.2)', 
                cursor: 'pointer',
                transition: 'all 0.4s ease' 
              }} 
            />
          ))}
        </div>
        <div style={{ display: 'flex', gap: 12 }}>
          <button onClick={prev} style={arrowStyle}>‹</button>
          <button onClick={next} style={arrowStyle}>›</button>
        </div>
      </div>

      <style>{`
        @keyframes float {
          0%, 100% { transform: translateY(0px); }
          50% { transform: translateY(-20px); }
        }
      `}</style>
    </section>
  );
}

const badgeStyle = {
  background: 'rgba(255,255,255,0.1)',
  padding: '6px 12px',
  borderRadius: '99px',
  fontSize: '11px',
  fontWeight: 700,
  color: '#fff',
  border: '1px solid rgba(255,255,255,0.1)'
};

const arrowStyle = {
  width: 44,
  height: 44,
  borderRadius: '50%',
  border: '1px solid rgba(255,255,255,0.2)',
  background: 'rgba(255,255,255,0.05)',
  color: '#fff',
  fontSize: '24px',
  cursor: 'pointer',
  display: 'flex',
  alignItems: 'center',
  justifyContent: 'center',
  backdropFilter: 'blur(10px)',
  transition: '0.3s'
};
